# backend/seed_maternal.py
import sqlite3
import json

def create_topic(section, title, intro, details, why, tips, myths, when_to_consult, takeaways, faqs):
    """Helper function to format the data and convert lists to JSON strings."""
    return {
        "section": section, "title": title, "intro": intro, "details": details, "why": why,
        "tips": json.dumps(tips), "myths": json.dumps(myths), "when_to_consult": when_to_consult,
        "takeaways": json.dumps(takeaways), "faqs": json.dumps(faqs)
    }

conn = sqlite3.connect('afyalink.db')
cursor = conn.cursor()

# 1. Create table if it doesn't exist
cursor.execute('''
    CREATE TABLE IF NOT EXISTS maternal_topics (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        section TEXT, language TEXT, title TEXT, intro TEXT, details TEXT, 
        why TEXT, tips TEXT, myths TEXT, when_to_consult TEXT, takeaways TEXT, faqs TEXT
    )
''')

# 2. Clear existing maternal data
cursor.execute("DELETE FROM maternal_topics;")

