def insert_data(data_list, lang_code):
    for item in data_list:
        cursor.execute('''
            INSERT INTO maternal_topics (
                section, language, title, intro, details, why, tips, myths, when_to_consult, takeaways, faqs
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ''', (
            item["section"], lang_code, item["title"], item["intro"], item["details"], item["why"],
            item["tips"], item["myths"], item["when_to_consult"], item["takeaways"], item["faqs"]
        ))

